```yaml
name: AI Docs Review Command

on:
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'Pull Request number to review'
        required: true
        type: string

permissions:
  contents: read
  pull-requests: write

jobs:
  ai-docs-review:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Node
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install jsonwebtoken
        run: npm install jsonwebtoken

      - name: Validate PR number
        if: ${{ github.event.inputs.pr_number == '' }}
        run: |
          echo "❌ Error: PR number is required."
          exit 1

      - name: Fetch changed files
        id: fetch
        uses: actions/github-script@v6
        with:
          script: |
            const core = require('@actions/core');
            const jwt = require('jsonwebtoken');

            const privateKey = Buffer.from(process.env.OCTAVIA_BOT_PRIVATE_KEY, 'base64').toString('utf8');
            const appId = process.env.OCTAVIA_BOT_APP_ID;
            const now = Math.floor(Date.now() / 1000);
            const payload = { iat: now - 60, exp: now + 600, iss: appId };
            const jwtToken = jwt.sign(payload, privateKey, { algorithm: 'RS256' });

            github.auth = jwtToken;

            const { data: installation } = await github.apps.getInstallation({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            const installationId = installation.id;

            const { data: tokenData } = await github.apps.createInstallationAccessToken({
              installation_id: installationId
            });
            const accessToken = tokenData.token;

            const prNumber = parseInt(github.event.inputs.pr_number, 10);

            const filesResponse = await github.request('GET /repos/{owner}/{repo}/pulls/{pull_number}/files', {
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
              per_page: 100,
              headers: { Authorization: `token ${accessToken}` }
            });

            const files = filesResponse.data;
            const connectorPattern = /^airbyte-integrations\/connectors\/[^/]+\/.*/;
            const hasConnector = files.some(f => connectorPattern.test(f.filename));

            core.setOutput('has_connector', hasConnector ? 'true' : 'false');

      - name: Post started comment
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = parseInt(github.event.inputs.pr_number, 10);
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: '🧠 AI Docs Review started.'
            });

      - name: Run Devin if connector changes
        if: steps.fetch.outputs.has_connector == 'true'
        uses: airbytehq/devin-action@v1
        with:
          devin-token: ${{ secrets.DEVIN_TOKEN }}
          org-id: ${{ secrets.DEVIN_ORG_ID }}
          macro: "!connectordocs_pr_review"
          pr_number: ${{ github.event.inputs.pr_number }}

      - name: Post skipped comment
        if: steps.fetch.outputs.has_connector == 'false'
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = parseInt(github.event.inputs.pr_number, 10);
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: '⚠️ No connector changes detected. Skipping AI Docs Review.'
            });

      - name: Post error comment
        if: failure()
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = parseInt(github.event.inputs.pr_number, 10);
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: '❌ AI Docs Review failed due to an error.'
            })
